type WorkspaceTool = 'Console' | 'Files' | 'Databases' | 'Domains' | 'Backups' | 'Schedules' | 'Environment' | 'Resources' | 'Activity' | 'Deployments' | 'Startup'

const toolFromNav: Record<string, WorkspaceTool> = { Console: 'Console', 'File Manager': 'Files', Files: 'Files', Databases: 'Databases', Domains: 'Domains', Backups: 'Backups', Schedules: 'Schedules', Environment: 'Environment', Resources: 'Resources', Activity: 'Activity', Deployments: 'Deployments', Startup: 'Startup' }

function Logo() {
  return <div className="brand-mark"><img className="brand-cloud" src="/logo.png" alt="LeaxPanel" /><span>Leax<span>Panel</span></span></div>
}

function EmptyState({ illustration, title, description, action }: { illustration: 'results' | 'database' | 'templates' | 'backups' | 'monitoring' | 'ai'; title: string; description: string; action?: ReactNode }) {
  return <div className="empty-state"><img src={`/illustrations/empty-no-${illustration}.png`} alt="" /><strong>{title}</strong><p>{description}</p>{action}</div>
}

function StatusPill({ status }: { status: string }) {
  const key = status.toLowerCase()
  return <span className={`status-pill ${key}`}><i />{status}</span>
}

function Metric({ icon, label, value, change, tone }: { icon: IconName; label: string; value: string; change: string; tone: string }) {
  return <div className="metric-card"><div className={`metric-icon ${tone}`}><Icon name={icon} size={18} /></div><div className="metric-copy"><span>{label}</span><strong>{value}</strong><small className={change.startsWith('+') ? 'positive' : change.startsWith('-') ? 'negative' : ''}>{change}</small></div></div>
}

function WorkflowCard({ workflow, onOpen }: { workflow: typeof workflows[number]; onOpen: () => void }) {
  return <article className="workflow-card" onClick={onOpen}>
    <div className="card-top"><div className={`workflow-orb ${workflow.color}`}><Icon name="workflow" size={20} /></div><div className="card-title"><h3>{workflow.name}</h3><p>{workflow.description}</p></div><button className="icon-button subtle" aria-label="More actions" onClick={(e) => e.stopPropagation()}><Icon name="more" /></button></div>
    <div className="card-meta"><StatusPill status={workflow.status} /><span className="last-run"><Icon name="clock" size={14} /> {workflow.last}</span><span className="node-count"><Icon name="nodes" size={14} /> {workflow.nodes} nodes</span></div>
    <div className="card-stats"><div><span>Executions</span><strong>{workflow.runs}</strong></div><div><span>Success rate</span><strong className={workflow.rate === '100%' ? 'green-text' : ''}>{workflow.rate}</strong></div><div><span>Next run</span><strong>{workflow.next}</strong></div></div>
    <div className="card-bottom"><div className="tag-row">{workflow.tags.map(tag => <span key={tag} className="tag">{tag}</span>)}</div><div className="owner-avatar">{workflow.owner}</div></div>
  </article>
}

